import CryptoKit
import Foundation
import XCTest
@testable import BridgeyMac

/// A reconnect recorded between two Bridgey session clients (rust/client) in which a file resumes (draft
/// files_resume_draft1): the resumable offer, files.resume.wait while the receiver re-reads its partial, files.resume,
/// files.resume.ack and only the bytes after the offset in binary frames. Every frame is opened with this app's own
/// decoder, envelope tags, fast frame code and AES-GCM, and the resume messages with the decoders the Mac uses, as
/// sender and as receiver. Generated by rust/client/src/vectors.rs.
final class SessionClientResumeVectorTests: XCTestCase {
    private struct Frame {
        let from: String
        let message: PairingMessage?
        let binary: Data?
    }

    private struct Vector {
        let sessionKey: Data
        let frames: [Frame]
        let ids: [String: String]
        let size: Int64
        let sha256: String
        let resumeAt: Int64
        let name: String
    }

    private func load() throws -> Vector {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/session-client-resume-v1.json").standardizedFileURL
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        var frames: [Frame] = []
        var ids: [String: String] = [:]
        for raw in try XCTUnwrap(object["frames"] as? [[String: Any]]) {
            let from = try XCTUnwrap(raw["from"] as? String)
            if let line = raw["line"] as? String {
                let message = try decodeProtocolMessage(Data(line.utf8))
                if message.kind == "pairing.offer" || message.kind == "pairing.answer" { ids[from] = message.deviceId }
                frames.append(Frame(from: from, message: message, binary: nil))
            } else {
                frames.append(Frame(from: from, message: nil, binary: try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(raw["binaryBase64"] as? String)))))
            }
        }
        let file = try XCTUnwrap(object["file"] as? [String: Any])
        XCTAssertEqual(file["pattern"] as? String, "byte i is (i * 31) mod 251")
        return Vector(sessionKey: try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["sessionKey"] as? String))), frames: frames, ids: ids,
                      size: try XCTUnwrap(file["size"] as? Int64), sha256: try XCTUnwrap(file["sha256"] as? String),
                      resumeAt: try XCTUnwrap(object["resumeAt"] as? Int64), name: try XCTUnwrap(file["name"] as? String))
    }

    private func open(_ message: PairingMessage, _ key: Data) throws -> Data {
        try decrypt(nonce: try XCTUnwrap(message.nonce), ciphertext: try XCTUnwrap(message.ciphertext), key: key)
    }

    private func pattern(_ count: Int64) -> Data { Data((0..<Int(count)).map { UInt8(($0 * 31) % 251) }) }

    func testEveryFrameIsTaggedOrSealedByItsSender() throws {
        let vector = try load()
        let envelopeKey = SessionSecurity.envelopeKey(sessionKey: vector.sessionKey)
        let frameKey = SessionSecurity.fastFrameKey(sessionKey: vector.sessionKey)
        var kinds = Set<String>()
        for frame in vector.frames {
            let sender = try XCTUnwrap(vector.ids[frame.from])
            if let bytes = frame.binary {
                XCTAssertNoThrow(try openFastFrameBody(kind: bytes[1], body: bytes.subdata(in: FastFrame.headerBytes..<bytes.count), key: frameKey, sender: sender))
                continue
            }
            guard let message = frame.message, !message.kind.hasPrefix("pairing.") else { continue }
            XCTAssertTrue(SessionSecurity.tagMatches(envelopeKey: envelopeKey, senderDeviceID: sender, message: message), message.kind)
            if message.ciphertext != nil { XCTAssertNoThrow(try open(message, vector.sessionKey), message.kind) }
            kinds.insert(message.kind)
        }
        for kind in ["features.update", "files.offer", "files.resume.wait", "files.resume", "files.resume.ack", "files.chunk.ack", "files.complete", "files.complete.ack"] {
            XCTAssertTrue(kinds.contains(kind), kind)
        }
        XCTAssertFalse(kinds.contains("files.accept"), "files.resume answers the offer instead of files.accept")
    }

    func testTheResumeDecodesWithTheMacsOwnCodeAndOnlyTheTailTravels() throws {
        let vector = try load()
        let key = vector.sessionKey
        let frameKey = SessionSecurity.fastFrameKey(sessionKey: key)
        let data = pattern(vector.size)
        XCTAssertEqual(Data(SHA256.hash(data: data)).base64EncodedString(), vector.sha256)
        var offer: FileOfferPayload?
        var order: [String] = []
        var resumeMaps = 0
        var chunks: [(sequence: Int64, data: Data)] = []
        // The Mac as the sender of this file: its own hashing pass, block hashes and answer.
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("bridgey-resume-vector-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let source = directory.appendingPathComponent(vector.name)
        try data.write(to: source)
        for frame in vector.frames {
            if let bytes = frame.binary {
                let payload = try openFastFrameBody(kind: bytes[1], body: bytes.subdata(in: FastFrame.headerBytes..<bytes.count), key: frameKey,
                                                    sender: try XCTUnwrap(vector.ids[frame.from]))
                XCTAssertEqual(payload.kind, FastFrame.chunkKind)
                XCTAssertEqual(payload.id, offer?.transferId)
                chunks.append((payload.sequence, payload.plaintext))
                order.append("binary")
                continue
            }
            guard let message = frame.message, !message.kind.hasPrefix("pairing.") else { continue }
            order.append(message.kind)
            switch message.kind {
            case "features.update":
                guard case let .state(_, drafts) = decodeFeatureState(try open(message, key)) else { return XCTFail("features decode") }
                if drafts[FileResume.featureKey] == true { resumeMaps += 1 }
            case "files.offer":
                let decoded = try JSONDecoder().decode(FileOfferPayload.self, from: try open(message, key))
                XCTAssertEqual(decoded.resumable?.value, true, "offered resumable")
                XCTAssertEqual(decoded.transferId, message.transferId)
                XCTAssertEqual(decoded.size, vector.size)
                XCTAssertEqual(decoded.sha256, vector.sha256)
                offer = decoded
            case "files.resume.wait":
                XCTAssertEqual(frame.from, "responder")
                XCTAssertNil(message.ciphertext, "outer only")
                XCTAssertEqual(message.transferId, offer?.transferId)
            case "files.resume":
                let transferID = try XCTUnwrap(offer?.transferId)
                let plain = try open(message, key)
                let (offset, prefix) = try XCTUnwrap(FileResume.parseResume(plain, transferID: transferID, size: vector.size))
                XCTAssertEqual(offset, vector.resumeAt)
                XCTAssertEqual(prefix, Data(SHA256.hash(data: data.prefix(Int(offset)))))
                // The Mac as sender would agree: its own answer from the hashes kept for the offer.
                let outgoing = try OutgoingFileTransfer(url: source, transferID: transferID, cancellation: FileCancellationToken())
                XCTAssertEqual(outgoing.offer.sha256, vector.sha256)
                let answer = outgoing.resumeAnswer(plain)
                XCTAssertEqual(answer.offset, offset)
                XCTAssertNil(answer.reason)
            case "files.resume.ack":
                let plain = try open(message, key)
                XCTAssertEqual(FileResume.parseAck(plain, transferID: try XCTUnwrap(offer?.transferId), proposed: vector.resumeAt), vector.resumeAt)
            case "files.complete":
                let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: try open(message, key)) as? [String: Any])
                XCTAssertEqual(payload["sha256"] as? String, vector.sha256)
            default:
                break
            }
        }
        XCTAssertEqual(resumeMaps, 2, "both ends show files_resume_draft1")
        func position(_ kind: String) throws -> Int { try XCTUnwrap(order.firstIndex(of: kind), kind) }
        XCTAssertLessThan(try position("files.offer"), try position("files.resume.wait"))
        XCTAssertLessThan(try position("files.resume.wait"), try position("files.resume"))
        XCTAssertLessThan(try position("files.resume"), try position("files.resume.ack"))
        XCTAssertLessThan(try position("files.resume.ack"), try position("binary"))
        XCTAssertLessThan(try position("binary"), try position("files.complete.ack"))
        XCTAssertEqual(chunks.map(\.sequence), Array(0..<Int64(chunks.count)), "sequences from 0")
        let tail = chunks.reduce(Data()) { $0 + $1.data }
        XCTAssertEqual(tail, data.subdata(in: Int(vector.resumeAt)..<data.count), "only the bytes after the offset travel")
    }

    /// The Mac as the receiver of the same exchange: a kept partial of the first 1 MiB, the recorded offer opens it,
    /// the re-read proposes the recorded offset, the recorded ack goes on, the recorded chunks complete the file.
    func testTheMacAsReceiverResumesFromTheRecordedMessages() throws {
        let vector = try load()
        let key = vector.sessionKey
        let frameKey = SessionSecurity.fastFrameKey(sessionKey: key)
        let data = pattern(vector.size)
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("bridgey-resume-receive-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let peer = try XCTUnwrap(vector.ids["initiator"])
        let partials = ResumePartials(fileURL: directory.appendingPathComponent("records/file-resume.json"))
        let part = "\(vector.name)\(FileResume.partSuffix)"
        try data.prefix(Int(vector.resumeAt) + 2000).write(to: directory.appendingPathComponent(part))
        let kept = ResumeRecord(peer: peer, size: vector.size, sha256: vector.sha256, length: vector.resumeAt,
                                prefix: Data(SHA256.hash(data: data.prefix(Int(vector.resumeAt)))).base64EncodedString(),
                                dir: directory.path, part: part, name: vector.name, updated: 0)
        partials.save(kept)
        partials.release(kept.partURL, keep: true)
        let access = ReceiveDirectoryAccess(url: directory, scoped: false)
        var transfer: IncomingFileTransfer?
        var sequence: Int64 = 0
        for frame in vector.frames where frame.from == "initiator" {
            if let bytes = frame.binary {
                let payload = try openFastFrameBody(kind: bytes[1], body: bytes.subdata(in: FastFrame.headerBytes..<bytes.count), key: frameKey, sender: peer)
                try XCTUnwrap(transfer).append(payload.plaintext, sequence: payload.sequence, maximumChunk: FastFrame.maximumPlaintext)
                sequence += 1
                continue
            }
            guard let message = frame.message else { continue }
            switch message.kind {
            case "files.offer":
                let offer = try JSONDecoder().decode(FileOfferPayload.self, from: try open(message, key))
                let opened = try XCTUnwrap(partials.openIncoming(offer, from: peer, access: access, resumable: offer.resumable?.value == true))
                guard case let .checking(length, _) = opened.phase else { return XCTFail("the kept partial is found") }
                XCTAssertEqual(length, vector.resumeAt)
                guard case let .propose(offset, payload) = opened.applyCheck(try? FileResume.hashPrefix(of: opened.partialURL, length: length)) else {
                    return XCTFail("the kept partial checks out")
                }
                XCTAssertEqual(offset, vector.resumeAt)
                XCTAssertEqual(FileResume.parseResume(payload, transferID: offer.transferId, size: offer.size)?.offset, offset)
                transfer = opened
            case "files.resume.ack":
                XCTAssertEqual(try XCTUnwrap(transfer).applyAck(try open(message, key)), .resume)
            case "files.complete":
                let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: try open(message, key)) as? [String: Any])
                let saved = try XCTUnwrap(transfer).finish(expectedHash: try XCTUnwrap(payload["sha256"] as? String))
                partials.finished(try XCTUnwrap(transfer))
                XCTAssertEqual(saved.lastPathComponent, vector.name)
                XCTAssertEqual(try Data(contentsOf: saved), data)
            default:
                break
            }
        }
        XCTAssertGreaterThan(sequence, 0)
        XCTAssertTrue(partials.store.records.isEmpty, "no record left")
        XCTAssertFalse(FileManager.default.fileExists(atPath: directory.appendingPathComponent(part).path), "no partial left")
    }
}
